#include <iostream>
#include <string>
#include <regex>

class _538A_CuttingBanner
{
private:
    static const std::string WORD;

    static bool doit(const std::string& word) {
        if (word.compare(0, WORD.size(), WORD) == 0 ||
            (word.size() >= WORD.size() && word.compare(word.size() - WORD.size(), WORD.size(), WORD) == 0))
            return true;

        for (size_t i = 1; i < WORD.length(); i++) {
            std::string pat = "^" + WORD.substr(0, i) + ".*" + WORD.substr(i) + "$";
            std::regex re(pat);
            if (std::regex_match(word, re)) return true;
        }
        return false;
    }

public:
    static void Run() {
        std::string s;
        std::getline(std::cin, s);

        bool ok = doit(s);

        std::cout << (ok ? "YES" : "NO") << std::endl;
    }
};

const std::string _538A_CuttingBanner::WORD = "CODEFORCES";

int main()
{
    _538A_CuttingBanner::Run();
    return 0;
}
